describe('Checkbox State Management', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/checkboxes');
  });

  it('should toggle checkbox states and update form correctly', () => {
    // Verify initial state: first checkbox unchecked, second checked
    cy.get('[data-testid="checkbox-one"]').should('have.value', '');
    cy.get('[data-testid="checkbox-two"]').should('have.value', 'on');

    // Verify form has correct initial state
    cy.get('[data-testid="form-status"]').should('contain', 'Both checkboxes are checked');

    // Toggle first checkbox
    cy.get('[data-testid="checkbox-one"]').click();

    // Verify first checkbox is now checked
    cy.get('[data-testid="checkbox-one"]').should('have.value', 'on');

    // Verify second checkbox remains checked
    cy.get('[data-testid="checkbox-two"]').should('have.value', 'on');

    // Verify form reflects updated state
    cy.get('[data-testid="form-status"]').should('contain', 'Both checkboxes are checked');

    // Toggle second checkbox
    cy.get('[data-testid="checkbox-two"]').click();

    // Verify first checkbox remains checked
    cy.get('[data-testid="checkbox-one"]').should('have.value', 'on');

    // Verify second checkbox is now unchecked
    cy.get('[data-testid="checkbox-two"]').should('have.value', '');

    // Verify form reflects updated state
    cy.get('[data-testid="form-status"]').should('contain', 'Only checkbox one is checked');
  });

  it('should handle edge case: toggling a disabled checkbox', () => {
    // Verify initial state: first checkbox unchecked, second checked
    cy.get('[data-testid="checkbox-one"]').should('have.value', '');
    cy.get('[data-testid="checkbox-two"]').should('have.value', 'on');

    // Verify form has correct initial state
    cy.get('[data-testid="form-status"]').should('contain', 'Both checkboxes are checked');

    // Toggle first checkbox
    cy.get('[data-testid="checkbox-one"]').click();

    // Verify first checkbox is now checked
    cy.get('[data-testid="checkbox-one"]').should('have.value', 'on');

    // Verify second checkbox remains checked
    cy.get('[data-testid="checkbox-two"]').should('have.value', 'on');

    // Verify form reflects updated state
    cy.get('[data-testid="form-status"]').should('contain', 'Both checkboxes are checked');

    // Disable first checkbox
    cy.get('[data-testid="checkbox-one"]').click();
    cy.get('[data-testid="checkbox-one"]').should('have.attr', 'disabled');

    // Toggle disabled first checkbox
    cy.get('[data-testid="checkbox-one"]').click();

    // Verify first checkbox remains disabled and unchecked
    cy.get('[data-testid="checkbox-one"]').should('have.attr', 'disabled');
    cy.get('[data-testid="checkbox-one"]').should('have.value', '');

    // Verify second checkbox remains checked
    cy.get('[data-testid="checkbox-two"]').should('have.value', 'on');

    // Verify form reflects updated state
    cy.get('[data-testid="form-status"]').should('contain', 'Only checkbox two is checked');
  });
});
